  if (warnifnotcap(curproxy, PR_CAP_FE, file, linenum, args[0], NULL))
    err_code |= ERR_WARN;

  if (!*(args[1])) {
    ha_alert("parsing [%s:%d] : '%s' expects {<path>|[addr1]:port1[-end1]}{,[addr]:port[-end]}... as arguments.\n",
